import {ICONS} from './plan-icons.js';
export const SCHEMA=1;
const validReminders=x=>x===null||Array.isArray(x)&&x.length<=5&&x.every(n=>Number.isInteger(n)&&n>=0&&n<=525600)&&new Set(x).size===x.length;
export const uid=()=>globalThis.crypto.randomUUID();
export function key(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
export function date(s){return new Date(`${s}T12:00:00`)}
export function add(s,n){const d=date(s);d.setDate(d.getDate()+n);return key(d)}
export function monday(s){const d=date(s);return add(s,-((d.getDay()+6)%7))}
export const areas={english:'İngilizce',curiosity:'Merak ve öğrenme',movement:'Hareket ve dinlenme',faith:'İbadet',social:'Aile ve ilişkiler',self:'Kişisel duruş',work:'İş',personal:'Kişisel'};
export function initial(today=key()) {const now=new Date().toISOString();return {schema:1,revision:0,prefs:{name:'',onboarded:false,focus:['english','movement','social'],prayerVisible:false,reviewDay:0,installDismissed:0,reminderDefaults:[1440,60],notifyEnabled:true,plannerMode:'week',quickVoice:false},items:[{id:'work-shift',title:'Depo vardiyası',kind:'event',date:monday(today),time:'16:00',endTime:'01:00',repeat:'weekly',weekdays:[1,2,3,4,5,6],area:'work',optional:false,priority:false,status:'pending',buffer:0,exceptions:{},history:[],createdAt:now,updatedAt:now}],notes:[],goals:[],days:{},reviews:[]}}
export function activeOn(item,day){if(day<item.date || item.until&&day>item.until)return false;if(item.repeat==='daily')return true;if(item.repeat==='weekly')return item.weekdays.includes(date(day).getDay());return day===item.date}
export function occurrence(item,origin){const ex=item.exceptions?.[origin]||{};return {...item,...ex,id:item.id,origin,date:ex.date||origin,repeat:item.repeat,status:ex.status||item.status||'pending',occurrenceKey:`${item.id}:${origin}`}}
export function bounds(item){if(!item.time)return null;const start=new Date(`${item.date}T${item.time}:00`);let end=new Date(start);if(item.endTime){end=new Date(`${item.date}T${item.endTime}:00`);if(end<=start)end.setDate(end.getDate()+1)}else end=new Date(+start+30*60000);return {start:+start,end:+end}}
export function entries(state,start,end=start){const list=[],seen=new Set();function put(it,origin){const o=occurrence(it,origin);if(o.status==='cancelled')return;const b=bounds(o);const relevant=o.date>=start&&o.date<=end || b&&o.date<start&&b.end>+new Date(`${start}T00:00:00`);if(relevant&&!seen.has(o.occurrenceKey)){list.push(o);seen.add(o.occurrenceKey)}}for(const it of state.items){for(let day=add(start,-1);day<=end;day=add(day,1))if(activeOn(it,day))put(it,day);for(const origin of Object.keys(it.exceptions||{}))if(activeOn(it,origin))put(it,origin)}return list.sort((a,b)=>(a.date+(a.time||'99')).localeCompare(b.date+(b.time||'99')))}
export function conflict(a,b){if(a.occurrenceKey===b.occurrenceKey||['postponed','cancelled'].includes(a.status)||['postponed','cancelled'].includes(b.status))return false;const x=bounds(a),y=bounds(b);if(!x||!y)return false;return x.start-(a.buffer||0)*60000<y.end+(b.buffer||0)*60000&&y.start-(b.buffer||0)*60000<x.end+(a.buffer||0)*60000}
export function setOccurrence(state,id,origin,patch,scope='one'){const item=state.items.find(i=>i.id===id);if(!item)throw Error('Kayıt bulunamadı.');const now=new Date().toISOString();if(item.repeat!=='none'&&scope==='one'){item.exceptions[origin]={...(item.exceptions[origin]||{}),...patch,updatedAt:now}}else Object.assign(item,patch,{updatedAt:now});item.history.push({at:now,origin,action:patch.status||'edited',scope});}
const object=x=>!!x&&typeof x==='object'&&!Array.isArray(x);
const str=(s,max=20000)=>typeof s==='string'&&s.length<=max;
const validDate=x=>typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x)&&!isNaN(+date(x))&&key(date(x))===x;
const validTime=x=>x===''||typeof x==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(x);
const statuses=['pending','done','postponed','cancelled'];
export function validateBackup(raw){if(raw&&'revision'in Object(raw)&&(!Number.isSafeInteger(raw.revision)||raw.revision<0))throw Error('Yedek sürümü geçersiz.');if(!object(raw)||raw.schema!==1||!object(raw.prefs)||!Array.isArray(raw.items)||!Array.isArray(raw.notes)||!Array.isArray(raw.goals)||!object(raw.days)||!Array.isArray(raw.reviews))throw Error('Bu dosya geçerli bir Gün Payı yedeği değil.');if(raw.items.length+raw.notes.length>30000)throw Error('Yedek çok büyük.');const ids=new Set();function checkId(x){if(!str(x,150)||!/^[-_a-zA-Z0-9]+$/.test(x)||ids.has(x))throw Error('Yedekte eksik veya yinelenen kayıt kimliği var.');ids.add(x)}function fields(i,partial=false){if(!partial||'title'in i)if(!str(i.title,500)||!i.title.trim())throw Error('Kayıt başlığı geçersiz.');if(!partial||'date'in i)if(!validDate(i.date))throw Error('Kayıt tarihi geçersiz.');for(const t of ['time','endTime'])if(t in i&&!validTime(i[t]))throw Error('Kayıt saati geçersiz.');if('status'in i&&!statuses.includes(i.status))throw Error('Kayıt durumu geçersiz.');if('buffer'in i&&(!Number.isFinite(i.buffer)||i.buffer<0||i.buffer>240))throw Error('Tampon süre geçersiz.');if('area'in i&&!(i.area in areas))throw Error('Kayıt alanı geçersiz.');if('icon'in i&&!(Object.hasOwn(ICONS,i.icon)))throw Error('Simge geçersiz.');if('reminders'in i&&!validReminders(i.reminders))throw Error('Hatırlatma süreleri geçersiz.');for(const b of ['optional','priority','rest'])if(b in i&&typeof i[b]!=='boolean')throw Error('Kayıt tercihi geçersiz.');}
for(const i of raw.items){if(!object(i))throw Error('Kayıt geçersiz.');checkId(i.id);fields(i);if(!str(i.createdAt,100)||!Number.isFinite(Date.parse(i.createdAt))||!str(i.updatedAt,100)||!Number.isFinite(Date.parse(i.updatedAt)))throw Error('Kayıt zamanı geçersiz.');if(!['task','event','habit'].includes(i.kind)||!['none','daily','weekly'].includes(i.repeat)||!Array.isArray(i.weekdays)||i.weekdays.some(d=>!Number.isInteger(d)||d<0||d>6)||i.repeat==='weekly'&&!i.weekdays.length||!object(i.exceptions)||!Array.isArray(i.history)||i.until&&!validDate(i.until))throw Error('Tekrar düzeni geçersiz.');for(const [d,x]of Object.entries(i.exceptions)){if(!validDate(d)||!object(x)||Object.keys(x).some(k=>!['title','date','time','endTime','status','buffer','area','optional','priority','rest','detail','updatedAt','reminders','icon'].includes(k)))throw Error('Tekrar istisnası geçersiz.');fields(x,true)}for(const h of i.history)if(!object(h)||!validDate(h.origin)||!str(h.at,100)||!Number.isFinite(Date.parse(h.at))||!['pending','done','postponed','cancelled','edited'].includes(h.action)||!['one','series'].includes(h.scope))throw Error('İşlem geçmişi geçersiz.');if(!str(i.detail||''))throw Error('Açıklama çok uzun.');}
for(const n of raw.notes){if(!object(n))throw Error('Not geçersiz.');checkId(n.id);if(!str(n.text)||!n.text.trim()||!str(n.tag,200)||!['remember','heard','idea','learning','conversation'].includes(n.kind)||!str(n.recall||'')||!str(n.use||'')||!Array.isArray(n.reviewDates)||n.reviewDates.some(x=>!validDate(x))||!Array.isArray(n.reviewedDates)||n.reviewedDates.some(x=>!validDate(x))||!str(n.createdAt,100)||!Number.isFinite(Date.parse(n.createdAt))||!str(n.updatedAt,100)||!Number.isFinite(Date.parse(n.updatedAt)))throw Error('Not içeriği geçersiz.');}
for(const g of raw.goals){if(!object(g))throw Error('Hedef geçersiz.');checkId(g.id);if(!str(g.createdAt,100)||!Number.isFinite(Date.parse(g.createdAt))||!str(g.updatedAt,100)||!Number.isFinite(Date.parse(g.updatedAt)))throw Error('Hedef zamanı geçersiz.');if(!(g.area in areas)||!['title','why','step','normal','hard'].every(k=>str(g[k],2000))||!Array.isArray(g.log)||g.log.some(x=>!object(x)||!validDate(x.date)||!str(x.mode,50)))throw Error('Hedef içeriği geçersiz.');}
for(const[d,v]of Object.entries(raw.days))if(!validDate(d)||!object(v)||v.energy&&!['low','medium','good'].includes(v.energy)||v.reflection&&!str(v.reflection))throw Error('Gün kaydı geçersiz.');
for(const r of raw.reviews){if(!object(r)||!validDate(r.week)||!Array.isArray(r.answers)||r.answers.length!==5||r.answers.some(x=>!str(x)))throw Error('Değerlendirme geçersiz.');}
if('telegramUserId'in raw.prefs&&(typeof raw.prefs.telegramUserId!=='string'||! /^[1-9]\d{3,19}$/.test(raw.prefs.telegramUserId)))throw Error('Telegram kullanıcı ID geçersiz.');if('telegramService'in raw.prefs&&(typeof raw.prefs.telegramService!=='string'||raw.prefs.telegramService.length>300))throw Error('Telegram servis adresi geçersiz.');
if('plannerMode'in raw.prefs&&!['week','list','month'].includes(raw.prefs.plannerMode))throw Error('Plan görünümü geçersiz.');if('quickVoice'in raw.prefs&&typeof raw.prefs.quickVoice!=='boolean')throw Error('Hızlı ekleme tercihi geçersiz.');
if('reminderDefaults'in raw.prefs&&(!Array.isArray(raw.prefs.reminderDefaults)||!validReminders(raw.prefs.reminderDefaults)))throw Error('Varsayılan hatırlatmalar geçersiz.');if('notifyEnabled'in raw.prefs&&typeof raw.prefs.notifyEnabled!=='boolean')throw Error('Bildirim tercihi geçersiz.');
if(!Array.isArray(raw.prefs.focus)||raw.prefs.focus.some(x=>!(x in areas))||typeof raw.prefs.onboarded!=='boolean'||typeof raw.prefs.prayerVisible!=='boolean'||!str(raw.prefs.name,100)||!Number.isInteger(raw.prefs.reviewDay)||raw.prefs.reviewDay<0||raw.prefs.reviewDay>6)throw Error('Tercihler geçersiz.');return structuredClone(raw)}
export function mergeBackup(current,incoming){const next=structuredClone(current);for(const type of ['items','notes','goals']){const map=new Map(next[type].map(x=>[x.id,x]));for(const x of incoming[type]){const old=map.get(x.id);if(!old||String(x.updatedAt||x.createdAt||'')>String(old.updatedAt||old.createdAt||''))map.set(x.id,x)}next[type]=[...map.values()]}next.days={...incoming.days,...next.days};const rev=new Map(incoming.reviews.map(x=>[x.week,x]));for(const x of next.reviews)rev.set(x.week,x);next.reviews=[...rev.values()];return next}
export function coaching(state,today){const out=[];for(const item of state.items){const count=item.history.filter(x=>x.action==='postponed').length;if(count>=3)out.push({title:item.title,text:`${count} kez ertelendi. Sonraki adımı küçültmeyi deneyebilirsin.`,id:item.id})}const week=entries(state,monday(today),add(monday(today),6));for(let i=0;i<7;i++){const d=add(monday(today),i),optional=week.filter(x=>x.date===d&&x.optional&&x.status==='pending');if(optional.length>3)out.push({title:'Aynı güne çok iş gelmiş',text:`${new Intl.DateTimeFormat('tr',{weekday:'long'}).format(date(d))}: ${optional.length} isteğe bağlı iş. Birini başka güne alabilirsin.`})}return out.slice(0,3)}
